//! AOT proof of a Guard return, cleanup and unwinding between two Dart functions.
//! The final argument `automatic` adds a propagator whose invoke,
//! landing pad, lexical close and cleanup are generated by the ARC preparation.
//! The additional argument `misto` gives the caller a prepared catch and another
//! automatic invoke, exercising the catch selector in the Unix cleanup profile.
//! Does not observe the final death nor certify the rest of the ARC pipeline.

use dartforge_emit_native::{driver, hir::*, llvm::LlvmEmitter, optimize::arc::*};
use std::{collections::HashMap, path::PathBuf};

fn main() -> Result<(), String> {
    let mut args = std::env::args().skip(1);
    let exit = PathBuf::from(args.next().ok_or("provide the output executable")?);
    let arc = args.next().as_deref() != Some("tracing");
    let throw = args.next().as_deref() == Some("error");
    let automatic = args.next().as_deref() == Some("automatic");
    let mixed = args.next().as_deref() == Some("mixed");
    if mixed && !automatic {
        return Err("mixed requires automatic preparation".into());
    }
    let val = |v| Operand::Val(ValueId(v));
    let runtime = |name: &str, args, ret_ty| Instruction::CallRuntime {
        name: name.into(),
        args,
        ret_ty,
    };
    let mut module = Module::new();
    module.arc_memory = arc;
    module.table_exceptions = true;
    module.entry_symbol = Some("prova_guardas".into());
    module.functions.push(Function {
        symbol: "prova_guardas".into(),
        name: "prova_guardas".into(),
        debug_info: None,
        params: vec![],
        return_ty: Type::Void,
        blocks: vec![
            BasicBlock {
                id: BlockId(0),
                instructions: vec![
                    (
                        ValueId(0),
                        runtime(
                            "dartforge_arc_box_int_owned_v1",
                            vec![(Operand::Constant(Constant::Int(i64::MAX)), Type::I64)],
                            Type::Ref,
                        ),
                        Type::Ref,
                    ),
                    (
                        ValueId(22),
                        runtime("dartforge_arc_stack_trace_owned_v1", vec![], Type::Ref),
                        Type::Ref,
                    ),
                    (
                        ValueId(1),
                        Instruction::CallStatic {
                            symbol: if automatic {
                                "propagador"
                            } else {
                                "retorno_guardado"
                            }
                            .into(),
                            args: vec![val(0), val(22)],
                            ret_ty: Type::Ref,
                        },
                        Type::Ref,
                    ),
                ],
                terminator: Terminator::CondBranch {
                    cond: Operand::Constant(Constant::Bool(false)),
                    then_block: BlockId(1),
                    else_block: BlockId(2),
                },
            },
            BasicBlock {
                id: BlockId(1),
                instructions: vec![(
                    ValueId(2),
                    runtime("dartforge_exception_clear", vec![], Type::Void),
                    Type::Void,
                )],
                terminator: Terminator::Return(None),
            },
            BasicBlock {
                id: BlockId(2),
                instructions: vec![
                    (
                        ValueId(3),
                        Instruction::ArcDrop { value: val(1) },
                        Type::Void,
                    ),
                    (
                        ValueId(8),
                        runtime("dartforge_arc_collect", vec![], Type::Void),
                        Type::Void,
                    ),
                    (
                        ValueId(4),
                        runtime(
                            "dartforge_print_handle",
                            vec![(val(0), Type::Ref)],
                            Type::Void,
                        ),
                        Type::Void,
                    ),
                    (
                        ValueId(5),
                        runtime("dartforge_exception_pending", vec![], Type::I8),
                        Type::I8,
                    ),
                    (
                        ValueId(6),
                        Instruction::ICmp(ICmpOp::Ne, val(5), Operand::Constant(Constant::Int(0))),
                        Type::I1,
                    ),
                ],
                terminator: Terminator::CondBranch {
                    cond: val(6),
                    then_block: BlockId(3),
                    else_block: BlockId(4),
                },
            },
            BasicBlock {
                id: BlockId(3),
                instructions: vec![(
                    ValueId(7),
                    runtime("dartforge_exception_clear", vec![], Type::Void),
                    Type::Void,
                )],
                terminator: Terminator::Return(None),
            },
            BasicBlock {
                id: BlockId(4),
                instructions: vec![],
                terminator: Terminator::Return(None),
            },
        ],
    });
    module.functions.push(Function {
        symbol: "retorno_guardado".into(),
        name: "retorno_guardado".into(),
        debug_info: None,
        params: vec![
            (ValueId(0), "x".into(), Type::Ref),
            (ValueId(2), "rastro".into(), Type::Ref),
        ],
        return_ty: Type::Ref,
        blocks: vec![BasicBlock {
            id: BlockId(0),
            instructions: if throw {
                vec![(
                    ValueId(1),
                    runtime(
                        "dartforge_arc_throw_with_stack_trace_ref_v1",
                        vec![(val(0), Type::Ref), (val(2), Type::Ref)],
                        Type::Void,
                    ),
                    Type::Void,
                )]
            } else {
                vec![]
            },
            terminator: Terminator::Return(Some(val(0))),
        }],
    });
    let mut caller = DartFunctionPlan::default();
    caller.tables.invocations.insert(ValueId(1), BlockId(1));
    caller.tables.landing_pads.insert(BlockId(1));
    let mut callee = DartFunctionPlan::default();
    callee.tokens.ret = TokenReturn::Owned;
    callee
        .tables
        .exits
        .insert(BlockId(0), ExceptionExit::Guard);
    let mut plans = HashMap::from([
        ("prova_guardas".into(), caller),
        ("retorno_guardado".into(), callee),
    ]);
    if automatic {
        module.functions.push(Function {
            symbol: "propagador".into(),
            name: "propagador".into(),
            debug_info: None,
            params: vec![
                (ValueId(0), "x".into(), Type::Ref),
                (ValueId(3), "rastro".into(), Type::Ref),
            ],
            return_ty: Type::Ref,
            blocks: vec![BasicBlock {
                id: BlockId(0),
                instructions: vec![
                    (
                        ValueId(1),
                        Instruction::ArcCopy { value: val(0) },
                        Type::Ref,
                    ),
                    (
                        ValueId(2),
                        Instruction::CallStatic {
                            symbol: "retorno_guardado".into(),
                            args: vec![val(1), val(3)],
                            ret_ty: Type::Ref,
                        },
                        Type::Ref,
                    ),
                ],
                terminator: Terminator::Return(Some(val(2))),
            }],
        });
        let mut propagator = DartFunctionPlan::default();
        propagator.tokens.ret = TokenReturn::Owned;
        propagator
            .scopes
            .before
            .insert(ValueId(2), vec![ScopeChange::Open(7)]);
        propagator
            .scopes
            .exits
            .insert(BlockId(0), vec![ScopeChange::Close(7)]);
        plans.insert("propagador".into(), propagator);
    }
    if mixed {
        // The initial catch stays explicit. The second invoke, without a catch,
        // makes the same function also receive Resume in the Unix prototype.
        module.functions[0]
            .blocks
            .iter_mut()
            .find(|b| b.id == BlockId(4))
            .unwrap()
            .instructions
            .push((
                ValueId(9),
                Instruction::CallStatic {
                    symbol: "propagador".into(),
                    args: vec![val(0), val(22)],
                    ret_ty: Type::Ref,
                },
                Type::Ref,
            ));
    }
    // Checks identity before the clear; then releases the original owner,
    // collects and reads the Owned copy, without depending on the pending root.
    let catch = module.functions[0]
        .blocks
        .iter_mut()
        .find(|b| b.id == BlockId(1))
        .unwrap();
    catch.instructions = vec![
        (
            ValueId(10),
            runtime("dartforge_arc_exception_owned_v1", vec![], Type::Ref),
            Type::Ref,
        ),
        (
            ValueId(11),
            Instruction::ICmp(ICmpOp::Ne, val(10), val(0)),
            Type::I1,
        ),
        (
            ValueId(23),
            runtime("dartforge_arc_stack_trace_owned_v1", vec![], Type::Ref),
            Type::Ref,
        ),
        (
            ValueId(24),
            Instruction::ICmp(ICmpOp::Ne, val(23), val(22)),
            Type::I1,
        ),
        (
            ValueId(2),
            runtime("dartforge_exception_clear", vec![], Type::Void),
            Type::Void,
        ),
        (
            ValueId(16),
            Instruction::ArcDrop { value: val(0) },
            Type::Void,
        ),
        (
            ValueId(27),
            Instruction::ArcDrop { value: val(22) },
            Type::Void,
        ),
        (
            ValueId(17),
            runtime("dartforge_arc_collect", vec![], Type::Void),
            Type::Void,
        ),
    ];
    // A retain after the collection checks that the capture of the stack trace is still alive.
    catch.instructions.push((
        ValueId(26),
        Instruction::ArcCopy { value: val(23) },
        Type::Ref,
    ));
    catch.terminator = Terminator::CondBranch {
        cond: val(11),
        then_block: BlockId(6),
        else_block: BlockId(12),
    };
    module.functions[0].blocks.extend([
        BasicBlock {
            id: BlockId(12),
            instructions: vec![],
            terminator: Terminator::CondBranch {
                cond: val(24),
                then_block: BlockId(6),
                else_block: BlockId(7),
            },
        },
        BasicBlock {
            id: BlockId(6),
            instructions: vec![
                // A change of identity produces null, distinct from the expected MAX.
                (
                    ValueId(12),
                    runtime(
                        "dartforge_print_handle",
                        vec![(Operand::Constant(Constant::Null), Type::Ref)],
                        Type::Void,
                    ),
                    Type::Void,
                ),
                (
                    ValueId(13),
                    runtime("dartforge_exception_pending", vec![], Type::I8),
                    Type::I8,
                ),
                (
                    ValueId(14),
                    Instruction::ICmp(ICmpOp::Ne, val(13), Operand::Constant(Constant::Int(0))),
                    Type::I1,
                ),
            ],
            terminator: Terminator::CondBranch {
                cond: val(14),
                then_block: BlockId(8),
                else_block: BlockId(9),
            },
        },
        BasicBlock {
            id: BlockId(7),
            instructions: vec![
                (
                    ValueId(18),
                    runtime(
                        "dartforge_print_handle",
                        vec![(val(10), Type::Ref)],
                        Type::Void,
                    ),
                    Type::Void,
                ),
                (
                    ValueId(19),
                    runtime("dartforge_exception_pending", vec![], Type::I8),
                    Type::I8,
                ),
                (
                    ValueId(20),
                    Instruction::ICmp(ICmpOp::Ne, val(19), Operand::Constant(Constant::Int(0))),
                    Type::I1,
                ),
            ],
            terminator: Terminator::CondBranch {
                cond: val(20),
                then_block: BlockId(10),
                else_block: BlockId(11),
            },
        },
        BasicBlock {
            id: BlockId(8),
            instructions: vec![(
                ValueId(15),
                runtime("dartforge_exception_clear", vec![], Type::Void),
                Type::Void,
            )],
            terminator: Terminator::Return(None),
        },
        BasicBlock {
            id: BlockId(9),
            instructions: vec![],
            terminator: Terminator::Return(None),
        },
        BasicBlock {
            id: BlockId(10),
            instructions: vec![(
                ValueId(21),
                runtime("dartforge_exception_clear", vec![], Type::Void),
                Type::Void,
            )],
            terminator: Terminator::Return(None),
        },
        BasicBlock {
            id: BlockId(11),
            instructions: vec![],
            terminator: Terminator::Return(None),
        },
    ]);
    let inserted = if automatic && arc {
        // The harness supplies the initial catch/exit CFG, like the exception pass of the
        // compiler. The integrated entry imports that inventory
        // and publishes the final CFG, including the invokes created in the propagator.
        module.tables = module
            .functions
            .iter()
            .map(|f| plans[&f.symbol].tables.clone())
            .collect();
        for plan in plans.values_mut() {
            plan.tables = FunctionTables::default();
        }
        prepare_arc_tabled_module(&mut module, &mut plans)?
    } else if automatic {
        prepare_arc_dart_functions(&mut module.functions, &mut plans)?
    } else {
        insert_arc_dart_functions(&mut module.functions, &mut plans)?
    };
    let expected = if mixed {
        (1, 17)
    } else if automatic {
        (1, 13)
    } else {
        (1, 16)
    };
    if inserted != expected {
        return Err(format!(
            "expected insertion {expected:?}, found {inserted:?}"
        ));
    }
    if !(automatic && arc) {
        module.tables = module
            .functions
            .iter()
            .map(|f| plans[&f.symbol].tables.clone())
            .collect();
    }
    let errors = dartforge_emit_native::lower::verifier::verify(&module);
    if !errors.is_empty() {
        return Err(errors.join("\n"));
    }
    let mut ir = LlvmEmitter::new(&module).emit_all();
    ir.push_str("\ndeclare void @dartforge_print_handle(i64)\n");
    if let Some(dir) = exit.parent() {
        std::fs::create_dir_all(dir).map_err(|e| e.to_string())?;
    }
    std::fs::write(exit.with_extension("ll"), &ir).map_err(|e| e.to_string())?;
    driver::compile_and_link(
        &ir,
        &exit,
        &driver::NativeDriverOptions {
            optimize: true,
            ..Default::default()
        },
    )?;
    Ok(())
}
